cd "$(git rev-parse --show-toplevel)" && cat <<'EOF' > lib/rate_limit.rb
# Counts how often something happens on a per-key basis, typically per client
# address, and says when something asks for more than its share.
#
# Counts live in memory only. Nothing is persisted, so there's no schema to
# migrate and nothing to clear by hand: attempts only stay counted while they're
# inside the window, so an address that quiets down is served again as soon as
# its burst ages out of it.
class RateLimit
  def initialize(limit:, within:)
    @limit = Integer(limit)
    @period = within.to_f

    @attempts = {}
    @lock = Mutex.new
    @next_sweep_at = 0.0
  end

  # Records an attempt made by identifier. Returns true when the identifier is
  # still within its limit, false when it has spent it and is turned away.
  def allow?(identifier)
    now = current_time

    @lock.synchronize do
      sweep_if_due(now)

      attempts = attempts_for(identifier)
      forget_expired(attempts, now)

      return false if attempts.size >= @limit

      attempts.push(now)
      true
    end
  end

  # Seconds until the next attempt by identifier can be allowed again.
  def retry_after(identifier)
    now = current_time

    @lock.synchronize do
      attempts = attempts_for(identifier)
      forget_expired(attempts, now)

      (attempts.first.to_f + @period - now).ceil.clamp(0..)
    end
  end

  # How many identifiers are being counted. Used to keep an eye on the memory
  # spent on remembering them.
  def size
    @lock.synchronize { @attempts.size }
  end

  private
    def attempts_for(identifier)
      @attempts[identifier] ||= []
    end

    def forget_expired(attempts, now)
      attempts.reject! { |attempt| attempt <= now - @period }
    end

    # Attempts made by addresses that went quiet are worthless to hold onto, so
    # drop those every now and then instead of growing without bound.
    def sweep_if_due(now)
      return if now < @next_sweep_at

      @attempts.delete_if { |_identifier, attempts| attempts.max.to_f <= now - @period }
      @next_sweep_at = now + @period
    end

    def current_time
      Time.now.to_f
    end
end
EOF
